package com.pudgy.raidpartychat;

import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Pure name logic, kept free of the client so it can be unit tested.
 */
final class PartyNames
{
	private static final Pattern TAGS = Pattern.compile("<[^>]*>");
	private static final Pattern SEPARATORS = Pattern.compile("[ _\\-\\s]+");
	private static final Pattern NAME_CHARS = Pattern.compile("[a-z0-9 ]{1,12}");
	private static final Pattern HAS_LETTER = Pattern.compile(".*[a-z].*");

	private PartyNames()
	{
	}

	/**
	 * Turns a widget text or chat name into one comparable form: tags (ironman icons, colours) removed,
	 * spaces, non-breaking spaces, underscores and hyphens treated alike, lower case.
	 */
	static String normalize(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		String s = TAGS.matcher(raw).replaceAll("");
		s = SEPARATORS.matcher(s).replaceAll(" ");
		return s.trim().toLowerCase();
	}

	/**
	 * True when a normalized widget text could be a player name (1 to 12 characters, letters, digits and
	 * spaces, at least one letter). Combat levels, stat columns and KC counts fail this test.
	 */
	static boolean looksLikeName(String normalized)
	{
		return normalized != null
			&& NAME_CHARS.matcher(normalized).matches()
			&& HAS_LETTER.matcher(normalized).matches();
	}

	/**
	 * Works out whose public chat to keep from one read of a party board.
	 *
	 * @param me                     the local player's normalized name
	 * @param members                names in the party (first one is the leader)
	 * @param applicants             names that have applied
	 * @param combined               true for a board that shows everyone in one list (Chambers of Xeric)
	 * @param includeOtherApplicants when I am only an applicant, also keep the other applicants
	 * @return the names to keep, or null when I am in neither list (I am just browsing someone's board)
	 */
	static Set<String> resolve(String me, List<String> members, List<String> applicants,
		boolean combined, boolean includeOtherApplicants)
	{
		if (me == null || me.isEmpty())
		{
			return null;
		}

		Set<String> keep = new LinkedHashSet<>();
		if (combined)
		{
			if (!members.contains(me) && !applicants.contains(me))
			{
				return null;
			}
			keep.addAll(members);
			keep.addAll(applicants);
			return keep;
		}

		if (members.contains(me))
		{
			keep.addAll(members);
			keep.addAll(applicants);
			return keep;
		}

		if (applicants.contains(me))
		{
			keep.addAll(members);
			if (includeOtherApplicants)
			{
				keep.addAll(applicants);
			}
			else
			{
				keep.add(me);
			}
			return keep;
		}

		return null;
	}
}

package com.pudgy.raidpartychat;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RaidPartyChatConfig.GROUP)
public interface RaidPartyChatConfig extends Config
{
	String GROUP = "raidpartychat";

	@ConfigItem(
		position = 1,
		keyName = "hideOverhead",
		name = "Hide overhead text",
		description = "Also hide the text above the heads of players who are not in your party"
	)
	default boolean hideOverhead()
	{
		return true;
	}

	@ConfigItem(
		position = 2,
		keyName = "showFriends",
		name = "Always show friends",
		description = "Keep showing public chat from people on your friends list"
	)
	default boolean showFriends()
	{
		return true;
	}

	@ConfigItem(
		position = 3,
		keyName = "includeOtherApplicants",
		name = "Show other applicants",
		description = "When you have applied to someone else's party, also show the other people who applied to it"
	)
	default boolean includeOtherApplicants()
	{
		return false;
	}

	@Range(min = 5, max = 200)
	@ConfigItem(
		position = 4,
		keyName = "range",
		name = "Lobby range (tiles)",
		description = "The filter stays on while you are within this many tiles of where you last had the party board open"
	)
	default int range()
	{
		return 40;
	}

	@ConfigItem(
		position = 5,
		keyName = "chatNotice",
		name = "Chat notice",
		description = "Post a game message when the filter turns on or off"
	)
	default boolean chatNotice()
	{
		return true;
	}
}

package com.pudgy.raidpartychat;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Raid Party Chat",
	description = "At a raid party board, public chat only shows your party and its applicants, or the party you applied to",
	tags = {"raid", "cox", "tob", "toa", "chambers", "theatre", "tombs", "fractured", "archive", "party", "chat", "filter", "lfg"}
)
public class RaidPartyChatPlugin extends Plugin
{
	/**
	 * One raid's party-details screen. {@code applicants} is -1 for a board that lists everyone together.
	 */
	private static final class Board
	{
		final String raid;
		final int root;
		final int members;
		final int applicants;

		Board(String raid, int root, int members, int applicants)
		{
			this.raid = raid;
			this.root = root;
			this.members = members;
			this.applicants = applicants;
		}
	}

	private static final Board[] BOARDS = {
		new Board("Chambers of Xeric", InterfaceID.RaidsLobbyPartydetails.UNIVERSE,
			InterfaceID.RaidsLobbyPartydetails.LIST, -1),
		new Board("Theatre of Blood", InterfaceID.TobPartydetails.UNIVERSE,
			InterfaceID.TobPartydetails.CURRENT, InterfaceID.TobPartydetails.APPLICANTS),
		new Board("Tombs of Amascut", InterfaceID.ToaPartydetails.UNIVERSE,
			InterfaceID.ToaPartydetails.MEMBERS_LIST, InterfaceID.ToaPartydetails.APPLICANTS_LIST),
		new Board("Fractured Archive", InterfaceID.TfaPartydetails.UNIVERSE,
			InterfaceID.TfaPartydetails.MEMBERS_LIST, InterfaceID.TfaPartydetails.APPLICANTS_LIST),
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private RaidPartyChatConfig config;

	/** Normalized names whose public chat stays visible. */
	private final Set<String> keep = new HashSet<>();
	/** Raid + leader of the party being tracked; a new party starts a fresh list. */
	private String partyKey;
	private String partyRaid;
	/** Where the board was last read; the filter switches off once you walk away from it. */
	private WorldPoint anchor;
	private boolean active;

	@Provides
	RaidPartyChatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RaidPartyChatConfig.class);
	}

	@Override
	protected void shutDown()
	{
		boolean wasActive = active;
		reset();
		if (wasActive)
		{
			clientThread.invoke(client::refreshChat);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RaidPartyChatConfig.GROUP.equals(event.getGroup()) && active)
		{
			clientThread.invoke(client::refreshChat);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}
		String me = PartyNames.normalize(local.getName());
		WorldPoint here = local.getWorldLocation();

		boolean grew = false;
		for (Board board : BOARDS)
		{
			Widget root = client.getWidget(board.root);
			if (root == null || root.isHidden())
			{
				continue;
			}

			List<String> members = names(board.members);
			List<String> applicants = board.applicants == -1 ? Collections.emptyList() : names(board.applicants);
			Set<String> party = PartyNames.resolve(me, members, applicants,
				board.applicants == -1, config.includeOtherApplicants());
			if (party == null)
			{
				// Browsing a board I am not part of: leave the tracked party alone
				log.debug("{} board open, {} not listed: members={} applicants={}", board.raid, me, members, applicants);
				continue;
			}

			String key = board.raid + "|" + (members.isEmpty() ? "" : members.get(0));
			if (!key.equals(partyKey))
			{
				keep.clear();
				partyKey = key;
				partyRaid = board.raid;
				grew = true;
			}
			grew |= keep.addAll(party);
			anchor = here;
			log.debug("{} board: members={} applicants={} keeping={}", board.raid, members, applicants, keep);
		}

		boolean nowActive = !keep.isEmpty() && anchor != null && here != null
			&& here.distanceTo(anchor) <= config.range();

		if (nowActive != active)
		{
			active = nowActive;
			if (active)
			{
				notice("Public chat now shows only your " + partyRaid + " party (" + keep.size() + " players).");
			}
			else
			{
				notice("Public chat is back to normal.");
				reset();
			}
			client.refreshChat();
		}
		else if (active && grew)
		{
			client.refreshChat();
		}
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!active || !"chatFilterCheck".equals(event.getEventName()))
		{
			return;
		}

		int[] intStack = client.getIntStack();
		int size = client.getIntStackSize();
		ChatMessageType type = ChatMessageType.of(intStack[size - 2]);
		if (type != ChatMessageType.PUBLICCHAT && type != ChatMessageType.MODCHAT && type != ChatMessageType.AUTOTYPER)
		{
			return;
		}

		MessageNode node = client.getMessages().get(intStack[size - 1]);
		if (node != null && !shouldShow(node.getName()))
		{
			intStack[size - 3] = 0;
		}
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!active || !config.hideOverhead() || !(event.getActor() instanceof Player))
		{
			return;
		}
		if (!shouldShow(event.getActor().getName()))
		{
			event.getActor().setOverheadText(" ");
		}
	}

	private boolean shouldShow(String rawName)
	{
		String name = PartyNames.normalize(rawName);
		if (name.isEmpty() || keep.contains(name))
		{
			return true;
		}
		Player local = client.getLocalPlayer();
		if (local != null && name.equals(PartyNames.normalize(local.getName())))
		{
			return true;
		}
		return config.showFriends() && client.isFriended(Text.removeTags(rawName), false);
	}

	/** Every text on the list that looks like a player name, in on-screen order. */
	private List<String> names(int componentId)
	{
		List<String> out = new ArrayList<>();
		Widget w = client.getWidget(componentId);
		if (w != null)
		{
			collect(w, out);
		}
		return out;
	}

	private static void collect(Widget w, List<String> out)
	{
		if (w.isSelfHidden())
		{
			return;
		}
		String n = PartyNames.normalize(w.getText());
		if (PartyNames.looksLikeName(n) && !out.contains(n))
		{
			out.add(n);
		}
		collectAll(w.getDynamicChildren(), out);
		collectAll(w.getStaticChildren(), out);
		collectAll(w.getNestedChildren(), out);
	}

	private static void collectAll(Widget[] children, List<String> out)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			if (child != null)
			{
				collect(child, out);
			}
		}
	}

	private void notice(String text)
	{
		if (!config.chatNotice())
		{
			return;
		}
		String msg = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("Raid Party Chat: ")
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(msg)
			.build());
	}

	private void reset()
	{
		keep.clear();
		partyKey = null;
		partyRaid = null;
		anchor = null;
		active = false;
	}
}

package com.pudgy.raidpartychat;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class PartyNamesTest
{
	private static List<String> l(String... s)
	{
		return Arrays.asList(s);
	}

	@Test
	public void normalizeMatchesChatAndWidgetForms()
	{
		// Chat names carry ironman icons and non-breaking spaces; widget names can carry colour tags
		assertEquals("pudgy penguin", PartyNames.normalize("<img=2>Pudgy Penguin"));
		assertEquals("pudgy penguin", PartyNames.normalize("<col=ffffff>Pudgy Penguin</col>"));
		assertEquals("pudgy penguin", PartyNames.normalize("Pudgy_Penguin"));
		assertEquals("pudgy penguin", PartyNames.normalize("Pudgy-Penguin"));
		assertEquals("", PartyNames.normalize(null));
	}

	@Test
	public void statColumnsAreNotNames()
	{
		assertFalse(PartyNames.looksLikeName("126"));
		assertFalse(PartyNames.looksLikeName("99"));
		assertFalse(PartyNames.looksLikeName("1,204"));
		assertFalse(PartyNames.looksLikeName(""));
		assertFalse(PartyNames.looksLikeName("a name far too long"));
		assertTrue(PartyNames.looksLikeName("pudgypenguin"));
		assertTrue(PartyNames.looksLikeName("zezima"));
		assertTrue(PartyNames.looksLikeName("x 2 x"));
	}

	@Test
	public void leaderKeepsMembersAndApplicants()
	{
		Set<String> keep = PartyNames.resolve("me", l("me", "friend"), l("app1", "app2"), false, false);
		assertEquals(Set.of("me", "friend", "app1", "app2"), keep);
	}

	@Test
	public void applicantKeepsThePartyButNotRivalApplicants()
	{
		Set<String> keep = PartyNames.resolve("me", l("leader", "member"), l("rival", "me"), false, false);
		assertEquals(Set.of("leader", "member", "me"), keep);
	}

	@Test
	public void applicantCanOptIntoOtherApplicants()
	{
		Set<String> keep = PartyNames.resolve("me", l("leader"), l("rival", "me"), false, true);
		assertEquals(Set.of("leader", "rival", "me"), keep);
	}

	@Test
	public void browsingSomeoneElsesBoardChangesNothing()
	{
		assertNull(PartyNames.resolve("me", l("leader", "member"), l("rival"), false, true));
		assertNull(PartyNames.resolve("", l("leader"), Collections.emptyList(), false, false));
	}

	@Test
	public void combinedBoardKeepsEveryoneWhenIAmListed()
	{
		assertEquals(Set.of("leader", "me", "other"),
			PartyNames.resolve("me", l("leader", "me", "other"), Collections.emptyList(), true, false));
		assertNull(PartyNames.resolve("me", l("leader", "other"), Collections.emptyList(), true, false));
	}
}

package com.pudgy.raidpartychat;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RaidPartyChatPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RaidPartyChatPlugin.class);
		RuneLite.main(args);
	}
}
